-- D04-021: a research-stage candidate cannot be ADMITTED to a source that does not exist.
--
-- candidate_id 1 carries disposition='ADMITTED' and notes 'RESOLVED: ... Admitted as
-- REF-00968'. The 2026-09-01 retraction deleted REF-00968 from evidence_sources. R15
-- passed anyway because its predicate is `notes LIKE '%RESOLVED%'`, and no rule joins
-- ADMITTED to evidence_sources -- so the row asserted an evidence-stage fact with no
-- target and nothing objected.
--
-- Re-dispositioned to PENDING-VERIFICATION, which is the live vocabulary's word for a
-- candidate whose standing is not yet established. The R15 'RESOLVED:' prefix is kept
-- because the re-description it refers to did happen; what changed is the admission,
-- not the reading.
--
-- The identity is NOT lost: REF-00968 is parked in source_locators as a research-stage
-- lead (data_20260902181820), so the note still names something that resolves.
UPDATE search_candidates
   SET disposition = 'PENDING-VERIFICATION',
       notes = notes || '  [RE-DISPOSITIONED 2026-09-02] The admission this row recorded was '
             || 'retracted by the owner ruling of 2026-09-01, which emptied evidence_sources. '
             || 'REF-00968 now exists as a research-stage lead in source_locators, not as '
             || 'admitted evidence, so this candidate is pending rather than admitted.'
 WHERE candidate_id = 1 AND disposition = 'ADMITTED';